function unique(list) {
  const seen = new Set();
  const result = [];
  for (const item of list) {
    if (!seen.has(item)) {
      result.push(item);
      seen.add(item);
    }
  }
  return result;
}

console.log(unique(["Rice", "Beans", "Rice", "Yam", "Beans"]).join(","));
console.log(unique([]).length);

