function stockValue(products) {
  let total = 0;
  for (const p of products) {
    if (p.quantity < 0) return "invalid";
    total = total + p.price * p.quantity;
  }
  return total;
}

console.log(stockValue([{ price: 250000, quantity: 4 }, { price: 99900, quantity: 10 }]));
