function topScorers(students) {
  let best = null;
  let names = [];
  for (const s of students) {
    if (best === null || s.score > best) {
      best = s.score;
      names = [s.name];
    } else if (s.score === best) {
      names.push(s.name);
    }
  }
  return names;
}

